-- ============================================================
-- STREAMLINED 5-TABLE DATABASE INITIALIZATION SCRIPT
-- Project: Personalized Career Recommendation System Using ML
-- Database Server: MySQL 8.x / MariaDB Compatible
-- Target Database: career_recommendation_db
-- Strictly 5 Modern Physical Tables:
--   1. users (Merged Authentication & Student Demographics)
--   2. questions (with options JSON)
--   3. assessment_sessions (with answers & scores JSON)
--   4. careers (with required_skills & recommended_subjects JSON)
--   5. career_recommendations (with match_breakdown JSON & ML confidence)
-- (All roadmaps and redundant fields completely removed)
-- ============================================================

CREATE DATABASE IF NOT EXISTS `career_recommendation_db`
CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE `career_recommendation_db`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Drop existing tables (both 5 clean tables and any obsolete legacy tables)
DROP TABLE IF EXISTS `career_recommendations`;
DROP TABLE IF EXISTS `assessment_sessions`;
DROP TABLE IF EXISTS `careers`;
DROP TABLE IF EXISTS `questions`;
DROP TABLE IF EXISTS `students`;
DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `career_pathways`;
DROP TABLE IF EXISTS `career_education`;
DROP TABLE IF EXISTS `career_subjects`;
DROP TABLE IF EXISTS `career_skills`;
DROP TABLE IF EXISTS `career_clusters`;
DROP TABLE IF EXISTS `career_subdomains`;
DROP TABLE IF EXISTS `career_domains`;
DROP TABLE IF EXISTS `assessment_scores`;
DROP TABLE IF EXISTS `student_answers`;
DROP TABLE IF EXISTS `question_options`;
DROP TABLE IF EXISTS `question_sections`;
DROP TABLE IF EXISTS `academic_scores`;
DROP TABLE IF EXISTS `learning_resources`;
DROP TABLE IF EXISTS `resources`;
DROP TABLE IF EXISTS `recommendation_feedback`;
DROP TABLE IF EXISTS `temp_recommendations`;

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================
-- 1. DDL SCHEMAS (STRICTLY 5 TABLES)
-- ============================================================

-- 1.1 Table: users (Unified Authentication & Student Demographics)
CREATE TABLE `users` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `username` VARCHAR(100) NOT NULL UNIQUE,
    `email` VARCHAR(255) NOT NULL UNIQUE,
    `password_hash` VARCHAR(255) NOT NULL,
    `role` ENUM('student', 'admin') NOT NULL DEFAULT 'student',
    `student_code` VARCHAR(50) NULL UNIQUE,
    `first_name` VARCHAR(100) NULL,
    `last_name` VARCHAR(100) NULL,
    `age` TINYINT UNSIGNED NULL,
    `gender` VARCHAR(30) NULL,
    `class_level` TINYINT UNSIGNED NULL,
    `board` VARCHAR(100) NULL DEFAULT 'CBSE',
    `medium` VARCHAR(50) NULL DEFAULT 'English',
    `stream` VARCHAR(100) NULL DEFAULT 'General',
    `academic_scores` JSON NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX `idx_users_role` (`role`),
    INDEX `idx_users_email` (`email`),
    INDEX `idx_users_username` (`username`),
    INDEX `idx_users_class` (`class_level`),
    INDEX `idx_users_stream` (`stream`),
    INDEX `idx_users_code` (`student_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 1.2 Table: questions (Roadmap and redundant fields removed)
CREATE TABLE `questions` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `question_code` VARCHAR(50) NOT NULL UNIQUE,
    `question_text` TEXT NOT NULL,
    `section` VARCHAR(100) NOT NULL DEFAULT 'General',
    `question_type` VARCHAR(50) NOT NULL DEFAULT 'MCQ',
    `class_min` SMALLINT NOT NULL DEFAULT 7,
    `class_max` SMALLINT NOT NULL DEFAULT 12,
    `difficulty` VARCHAR(20) DEFAULT 'Medium',
    `skill_category` VARCHAR(100) NULL,
    `stream_specific` VARCHAR(50) NULL DEFAULT 'All',
    `display_order` INT DEFAULT 0,
    `options` JSON NOT NULL,
    `is_active` BOOLEAN DEFAULT TRUE,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX `idx_questions_code` (`question_code`),
    INDEX `idx_questions_section` (`section`),
    INDEX `idx_questions_skill` (`skill_category`),
    INDEX `idx_questions_class` (`class_min`, `class_max`),
    INDEX `idx_questions_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 1.3 Table: assessment_sessions (Foreign key links directly to users.id)
CREATE TABLE `assessment_sessions` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `student_id` BIGINT UNSIGNED NOT NULL,
    `status` ENUM('not_started', 'in_progress', 'completed', 'abandoned') NOT NULL DEFAULT 'not_started',
    `started_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `completed_at` TIMESTAMP NULL,
    `current_question` INT DEFAULT 0,
    `completion_percentage` FLOAT DEFAULT 0.0,
    `selected_question_ids` TEXT NULL,
    `answers` JSON NULL,
    `scores` JSON NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_sessions_user` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    INDEX `idx_sessions_student` (`student_id`),
    INDEX `idx_sessions_status` (`status`),
    INDEX `idx_sessions_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 1.4 Table: careers (Roadmap fields removed)
CREATE TABLE `careers` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `career_code` VARCHAR(50) NULL,
    `career_name` VARCHAR(200) NOT NULL,
    `domain` VARCHAR(150) NOT NULL DEFAULT 'General',
    `subdomain` VARCHAR(150) NULL,
    `cluster` VARCHAR(150) NULL,
    `description` TEXT NULL,
    `minimum_education` VARCHAR(150) NULL,
    `typical_education` VARCHAR(150) NULL,
    `market_demand` VARCHAR(50) DEFAULT 'High',
    `growth_rate` VARCHAR(50) DEFAULT '10-15%',
    `avg_starting_salary` VARCHAR(100) DEFAULT '₹4,00,000 - ₹6,00,000',
    `salary_mid_career` VARCHAR(100) DEFAULT '₹12,00,000 - ₹18,00,000',
    `required_skills` JSON NULL,
    `recommended_subjects` JSON NULL,
    `is_active` BOOLEAN DEFAULT TRUE,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX `idx_careers_code` (`career_code`),
    INDEX `idx_careers_name` (`career_name`),
    INDEX `idx_careers_domain` (`domain`),
    INDEX `idx_careers_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 1.5 Table: career_recommendations (ML confidence & match breakdown added)
CREATE TABLE `career_recommendations` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `assessment_id` BIGINT UNSIGNED NOT NULL,
    `career_id` BIGINT UNSIGNED NOT NULL,
    `rank_position` INT NOT NULL DEFAULT 1,
    `score` FLOAT NULL,
    `is_decisive` TINYINT(1) DEFAULT 0,
    `probability` FLOAT NULL,
    `recommendation_reason` TEXT NULL,
    `strengths` TEXT NULL,
    `skill_gaps` TEXT NULL,
    `match_breakdown` JSON NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_recs_assessment` FOREIGN KEY (`assessment_id`) REFERENCES `assessment_sessions` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_recs_career` FOREIGN KEY (`career_id`) REFERENCES `careers` (`id`) ON DELETE CASCADE,
    INDEX `idx_recs_assessment` (`assessment_id`),
    INDEX `idx_recs_career` (`career_id`),
    INDEX `idx_recs_rank` (`assessment_id`, `rank_position`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

